//! Compare controlled insertion and lookup against twelve retained native rows.
use spore_core::{cell_provider_insert_lookup_join_v1::project,cell_provider_priority_scan_v1::Node};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native stdout")).unwrap();assert_eq!(b.len(),384);for i in 0..12{let k=i%6;let cw=if i>=6{0x37f}else{0x27f};let mut nodes=vec![Node{key:0x12345678,value:11,priority:1},Node{key:0x12345678,value:22,priority:2}];match k{0=>nodes.clear(),1=>{nodes[0].key=0x99999999;nodes[1].key=0x99999999},3=>nodes[1].priority=1,4=>nodes[0].priority=-1,5=>nodes[0].key=0x99999999,_=>{}}let x=project(0x12345678,&nodes,Node{key:0x12345678,value:33,priority:3},cw,0x1f80,true).unwrap();let expected=match k{0=>vec![33],1=>vec![33,11,22],5=>vec![11,22,33],_=>vec![11,33,22]};assert_eq!(x.nodes.iter().map(|n|n.value).collect::<Vec<_>>(),expected);let row=&b[i*32..(i+1)*32];assert_eq!((w(row,0),w(row,4),w(row,8),w(row,12)),(x.selected.unwrap_or(0),i as u32,1,1));let fp=w(row,16);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,20)&!0x3f,0x1f80);}println!("matched 12 retained successful insertion/lookup rows; synthetic lifecycle admitted");}
